-- create-table /TRFIN/BANK_ACCOUNTS
CREATE TABLE "/TRFIN/BANK_ACCOUNTS" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "IBAN" TEXT NOT NULL,
  "BALANCE" INTEGER NOT NULL DEFAULT 0,
  "OPENED_AT" TEXT,
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#ACCOUNT_NO" CHECK ("ACCOUNT_NO" IS NULL OR ("ACCOUNT_NO" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#IBAN" CHECK ("IBAN" IS NULL OR (length("IBAN") <= 34)),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#BALANCE" CHECK ("BALANCE" IS NULL OR ("BALANCE" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#CK#OPENED_AT" CHECK ("OPENED_AT" IS NULL OR ("OPENED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("OPENED_AT", 1, 19)) IS substr("OPENED_AT", 1, 19)))
) STRICT;

-- create-table /TRFIN/COMPANIES
CREATE TABLE "/TRFIN/COMPANIES" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  "/TROTTO/OTTO_ID" TEXT,
  CONSTRAINT "/TRFIN/COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "/TRFIN/COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON"))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/TROTTO/OTTO_ID" CHECK ("/TROTTO/OTTO_ID" IS NULL OR (length("/TROTTO/OTTO_ID") <= 20))
) STRICT;

-- create-table /TRFIN/COUNTRIES
CREATE TABLE "/TRFIN/COUNTRIES" (
  "COUNTRY_CODE" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "CURRENCY" TEXT,
  CONSTRAINT "/TRFIN/COUNTRIES#PK" PRIMARY KEY ("COUNTRY_CODE"),
  CONSTRAINT "/TRFIN/COUNTRIES#CK#COUNTRY_CODE" CHECK ("COUNTRY_CODE" IS NULL OR (length("COUNTRY_CODE") <= 2)),
  CONSTRAINT "/TRFIN/COUNTRIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "/TRFIN/COUNTRIES#CK#CURRENCY" CHECK ("CURRENCY" IS NULL OR (length("CURRENCY") <= 3))
) STRICT;

-- create-table /TRFIN/EXCHANGE_RATES
CREATE TABLE "/TRFIN/EXCHANGE_RATES" (
  "FROM_CURRENCY" TEXT NOT NULL,
  "TO_CURRENCY" TEXT NOT NULL,
  "VALID_FROM" TEXT NOT NULL,
  "RATE" INTEGER NOT NULL,
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#PK" PRIMARY KEY ("FROM_CURRENCY", "TO_CURRENCY", "VALID_FROM"),
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#CK#FROM_CURRENCY" CHECK ("FROM_CURRENCY" IS NULL OR (length("FROM_CURRENCY") <= 3)),
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#CK#TO_CURRENCY" CHECK ("TO_CURRENCY" IS NULL OR (length("TO_CURRENCY") <= 3)),
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#CK#VALID_FROM" CHECK ("VALID_FROM" IS NULL OR ("VALID_FROM" IS date("VALID_FROM"))),
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#CK#RATE" CHECK ("RATE" IS NULL OR ("RATE" BETWEEN -999999999999999 AND 999999999999999))
) STRICT;

-- create-table /TRFIN/PAYMENTS
CREATE TABLE "/TRFIN/PAYMENTS" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "PAYMENT_NO" INTEGER NOT NULL,
  "AMOUNT" INTEGER NOT NULL,
  "CURRENCY" TEXT NOT NULL,
  "BOOKED_AT" TEXT NOT NULL,
  CONSTRAINT "/TRFIN/PAYMENTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO", "PAYMENT_NO"),
  CONSTRAINT "/TRFIN/PAYMENTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRFIN/PAYMENTS#FK#ACCOUNT" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO") REFERENCES "/TRFIN/BANK_ACCOUNTS" ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#ACCOUNT_NO" CHECK ("ACCOUNT_NO" IS NULL OR ("ACCOUNT_NO" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#AMOUNT" CHECK ("AMOUNT" IS NULL OR ("AMOUNT" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#CURRENCY" CHECK ("CURRENCY" IS NULL OR (length("CURRENCY") <= 3)),
  CONSTRAINT "/TRFIN/PAYMENTS#CK#BOOKED_AT" CHECK ("BOOKED_AT" IS NULL OR ("BOOKED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("BOOKED_AT", 1, 19)) IS substr("BOOKED_AT", 1, 19)))
) STRICT;

-- create-table /TROTTO/OTTO_CONNECTIONS
CREATE TABLE "/TROTTO/OTTO_CONNECTIONS" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "ENDPOINT" TEXT NOT NULL,
  "ACTIVE" INTEGER NOT NULL DEFAULT 1,
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#CK#ACTIVE" CHECK ("ACTIVE" IS NULL OR ("ACTIVE" IN (0, 1)))
) STRICT;

